/**
 * Unit tests for StringUtils.join(Object[] array, String separator, int startIndex, int endIndex)
 */
public class StringUtils_join_TriageGen2Test {









    @Test
    public void testJoin_SingleElement() {
        Object[] array = {"A", "B", "C"};
        // startIndex = 1, endIndex = 2 -> noOfItems = 1
        // Logic: loop i=1; i<2; i++ -> buf.append(",") -> buf.append("B")
        // Note: Based on the provided code, it appends the separator BEFORE the first element in the range.
        assertEquals(",B", StringUtils.join(array, ",", 1, 2));
    }










}

