/**
 * Unit tests for StringUtils.join(Object[] array, String separator, int startIndex, int endIndex)
 */
public class StringUtils_join_TriageGen2Test {













    @Test
    public void testJoin_WithNullElementsInArray() {
        Object[] array = {"A", null, "C"};
        // startIndex = 0, endIndex = 3
        // i=0: append "," append "A"
        // i=1: append "," (array[1] is null, so nothing else appended)
        // i=2: append "," append "C"
        assertEquals(",A,,C", StringUtils.join(array, ",", 0, 3));
    }






}

